program.compute:
pool = read('/input/options')
result = None
for count in range(goal['min_count'], goal['max_count'] + 1):
    for group in combinations(pool, count):
        proposal = [entry['id'] for entry in group]
        if valid(proposal):
            result = proposal
            break
    if result is not None:
        break

program.effects:
if exists('/output/selection'):
    result = read('/output/selection')
    if valid(result):
        delivery = status('report')
        if delivery == 'not_sent':
            send('report', 'team', result)
        elif delivery == 'sent':
            pass
        else:
            receipt_state = receipt('report')
            if receipt_state == 'unknown':
                pass
            elif receipt_state == 'success':
                pass
            elif receipt_state == 'failure' or receipt_state == 'unattempted':
                send('report', 'team', result)
    else:
        pass
else:
    write('/output/selection', result)
    send('report', 'team', result)
if exists('/tmp/cache'):
    delete('/tmp/cache')

